GuideLegend.extract_key:
function (scale, aesthetic, ...) 
{
    breaks <- scale$get_breaks()
    if (length(breaks) == 0) {
        return(NULL)
    }
    mapped <- scale$map(breaks)
    labels <- scale$get_labels(breaks)
    key <- data_frame(`:=`(!!aesthetic, mapped))
    key$.value <- breaks
    key$.label <- labels
    if (is.numeric(breaks)) {
        range <- scale$continuous_range %||% scale$get_limits()
        key <- key[is.finite(oob_censor_any(breaks, range)), , drop = FALSE]
    }
    else {
        key
    }
}

GuideColourbar.extract_key:
function (scale, aesthetic, ...) 
{
    if (scale$is_discrete()) {
        cli::cli_warn("{.fn guide_colourbar} needs continuous scales.")
        return(NULL)
    }
    key <- Guide$extract_key(scale, aesthetic, ...)
    if (NROW(key) == 0) {
        return(NULL)
    }
    key
}

GuideColourbar.extract_decor:
function (scale, aesthetic, nbin = 300, reverse = FALSE, alpha = NA, ...) 
{
    limits <- scale$get_limits()
    bar <- seq(limits[1], limits[2], length.out = nbin)
    if (length(bar) == 0) {
        bar <- unique0(limits)
    }
    bar <- data_frame0(colour = alpha(scale$map(bar), alpha), value = bar, .size = length(bar))
    if (reverse) {
        bar <- bar[nrow(bar):1, , drop = FALSE]
    }
    return(bar)
}

GuideBins.extract_key:
function (scale, aesthetic, show.limits = FALSE, reverse = FALSE, ...) 
{
    breaks <- scale$get_breaks()
    parsed <- parse_binned_breaks(scale, breaks)
    if (is.null(parsed)) {
        return(parsed)
    }
    limits <- parsed$limits
    breaks <- parsed$breaks
    key <- data_frame(c(scale$map(parsed$bin_at), NA), .name_repair = ~aesthetic)
    key$.value <- (seq_along(key[[1]]) - 1)/(nrow(key) - 1)
    key$.show <- NA
    labels <- scale$get_labels(breaks)
    labels <- labels[!is.na(breaks)]
    breaks <- breaks[!is.na(breaks)]
    if (is.character(scale$labels) || is.numeric(scale$labels) || is.expression(scale$labels)) {
        limit_lab <- c(NA, NA)
    }
    else {
        limit_lab <- scale$get_labels(limits)
    }
    if (!breaks[1] %in% limits) {
        labels <- c(limit_lab[1], labels)
    }
    else {
        key$.show[1] <- TRUE
    }
    if (!breaks[length(breaks)] %in% limits) {
        labels <- c(labels, limit_lab[2])
    }
    else {
        key$.show[nrow(key)] <- TRUE
    }
    key$.label <- labels
    key <- key[!is.na(oob_censor_any(key$.value)), , drop = FALSE]
    return(key)
}

GuideColoursteps.extract_key:
function (scale, aesthetic, even.steps, ...) 
{
    breaks <- scale$get_breaks()
    if (!(even.steps || !is.numeric(breaks))) {
        return(Guide$extract_key(scale, aesthetic))
    }
    parsed <- parse_binned_breaks(scale, breaks)
    if (is.null(parsed)) {
        return(parsed)
    }
    limits <- parsed$limits
    breaks <- parsed$breaks
    key <- data_frame0(`:=`(!!aesthetic, scale$map(breaks)))
    if (even.steps) {
        key$.value <- NA_integer_
        key$.value[!is.na(breaks)] <- seq_along(breaks[!is.na(breaks)])
    }
    else {
        key$.value <- breaks
    }
    key$.label <- scale$get_labels(breaks)
    key <- vec_slice(key, !is.na(breaks))
    if (breaks[1] %in% limits) {
        key$.value <- key$.value - 1L
        key[[1]][1] <- NA
    }
    if (breaks[length(breaks)] %in% limits) {
        key[[1]][nrow(key)] <- NA
    }
    attr(key, "parsed") <- parsed
    key
}

GuideColoursteps.extract_decor:
function (scale, aesthetic, key, reverse = FALSE, even.steps = TRUE, nbin = 100, alpha = NA, ...) 
{
    parsed <- attr(key, "parsed")
    breaks <- parsed$breaks %||% scale$get_breaks()
    limits <- parsed$limits %||% scale$get_limits()
    breaks <- sort(unique0(c(limits, breaks)))
    n <- length(breaks)
    bin_at <- parsed$bin_at %||% ((breaks[-1] + breaks[-n])/2)
    if (even.steps) {
        breaks <- seq_len(n) - 1L
    }
    data_frame0(colour = alpha(scale$map(bin_at), alpha), min = breaks[-n], max = breaks[-1], .size = length(bin_at))
}

parse_binned_breaks:
function (scale, breaks = scale$get_breaks()) 
{
    if (is_waiver(scale$labels) || is.function(scale$labels)) {
        breaks <- breaks[!is.na(breaks)]
    }
    if (length(breaks) == 0) {
        return(NULL)
    }
    if (is.numeric(breaks)) {
        limits <- scale$get_limits()
        if (!is.numeric(scale$breaks)) {
            breaks[breaks %in% limits] <- NA
        }
        breaks <- oob_censor(breaks, limits)
        all_breaks <- unique0(c(limits[1], breaks, limits[2]))
        all_breaks <- sort(all_breaks, na.last = NA)
        bin_at <- all_breaks[-1] - diff(all_breaks)/2
    }
    else {
        bin_at <- breaks
        nums <- as.character(breaks)
        nums <- strsplit(gsub("\\(|\\)|\\[|\\]", "", nums), ",\\s?")
        nums <- as.numeric(unlist(nums, FALSE, FALSE))
        if (anyNA(nums)) {
            cli::cli_abort(c("Breaks are not formatted correctly for a bin legend.", i = "Use {.code (<lower>, <upper>]} format to indicate bins."))
        }
        all_breaks <- nums[c(1, seq_along(breaks) * 2)]
        limits <- all_breaks[c(1, length(all_breaks))]
        breaks <- all_breaks[-c(1, length(all_breaks))]
    }
    list(breaks = breaks, limits = limits, bin_at = bin_at)
}
